  "description": "MissionCache plugin hooks for context preservation and task detection",
  "modules": ["./mod/missioncache.tsx"],
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "uv",
            "args": ["run", "--quiet", "--no-project", "--frozen", "--python", ">=3.11", "python", "${CLAUDE_PLUGIN_ROOT}/hooks/activity_tracker.py"],
            "timeout": 5
          },
          {
            "type": "command",
            "command": "uv",
            "args": ["run", "--quiet", "--no-project", "--frozen", "--python", ">=3.11", "python", "${CLAUDE_PLUGIN_ROOT}/hooks/task_tracker.py"],
            "timeout": 5
          },
          {
            "type": "command",
            "command": "uv",
            "args": ["run", "--quiet", "--no-project", "--frozen", "--python", ">=3.11", "python", "${CLAUDE_PLUGIN_ROOT}/hooks/session_title.py"],
            "timeout": 5
          }
        ]
      }
    ],
